/**
 * Represents a team member with relevant information.
 */
export interface TeamProp {
  /**
   * The name of the team member.
   */
  name: string;

  /**
   * The position or role of the team member.
   */
  position: string;

  /**
   * The URL or path to the photo/image of the team member.
   */
  photo: string;
}
